mapper.select:
SELECT VENDOR_CODE AS VC_CODE , VENDOR_NAME AS VC_NAME , VENDOR_NAME_ENG AS VC_NAME_ENG , BUSINESS_NO , OFFICER_NAME , OFFICER_NAME_ENG , NATION_CODE , ADDRESS , ADDRESS_ENG , TEL_NO , FAX_NO , IMPORTANCE_MGT_YN AS MGT_YN , REMARK FROM VENDOR WHERE COMPANY_CODE = #{company_code}
AND (VENDOR_CODE LIKE CONCAT(#{searchCode}, '%') OR VENDOR_NAME LIKE CONCAT(#{searchCode}, '%'))
AND IMPORTANCE_MGT_YN = #{searchMgtYn}
ORDER BY VENDOR_CODE
